import unittest

from alpha.greeting import greeting


class TestGreeting(unittest.TestCase):
    def test_default(self):
        self.assertEqual(greeting(), "hello, demo")

    def test_none(self):
        self.assertEqual(greeting(None), "hello, demo")

    def test_name(self):
        self.assertEqual(greeting("Ada"), "hello, Ada")

    def test_limit_64_code_points_ok(self):
        self.assertEqual(greeting("x" * 64), "hello, " + "x" * 64)

    def test_limit_counts_code_points(self):
        name = "\U0001F600" * 64  # 64 code points, 256 bytes in UTF-8
        self.assertEqual(greeting(name), "hello, " + name)

    def test_over_limit(self):
        with self.assertRaises(ValueError) as cm:
            greeting("x" * 65)
        self.assertIn("64", str(cm.exception))


if __name__ == "__main__":
    unittest.main()

NAME_LIMIT_CODE_POINTS = 64


def greeting(name: str | None = None) -> str:
    if name is None:
        return "hello, demo"
    if len(name) > NAME_LIMIT_CODE_POINTS:
        raise ValueError(
            f"name exceeds the {NAME_LIMIT_CODE_POINTS}-character limit "
            f"(counted as Unicode code points)"
        )
    return f"hello, {name}"

import unittest

from alpha.limits import check_name


class CheckNameTest(unittest.TestCase):
    def test_64_code_points_ok(self):
        self.assertIsNone(check_name("a" * 64))

    def test_empty_ok(self):
        self.assertIsNone(check_name(""))

    def test_65_code_points_raises_naming_limit(self):
        with self.assertRaises(ValueError) as cm:
            check_name("a" * 65)
        self.assertIn("64", str(cm.exception))

    def test_counts_code_points_not_bytes(self):
        # 64 two-byte (U+00E9) and 64 four-byte (U+1F600) code points pass
        check_name("é" * 64)
        check_name("\U0001F600" * 64)
        with self.assertRaises(ValueError):
            check_name("\U0001F600" * 65)

    def test_combining_marks_count_as_code_points(self):
        # 33 x (e + U+0301) = 66 code points, 33 visible characters
        with self.assertRaises(ValueError):
            check_name("é" * 33)


if __name__ == "__main__":
    unittest.main()
